internal fun sharpVectorIndex(codePoint: Int): Int {
    var low = 0
    var high = sharpVectorCodePoints.lastIndex
    while (low <= high) {
        val middle = (low + high).ushr(1)
        val candidate = sharpVectorCodePoints[middle]
        when {
            candidate < codePoint -> low = middle + 1
            candidate > codePoint -> high = middle - 1
            else -> return middle
        }
    }
    return -1
}

internal fun sharpVectorPathAt(index: Int): String {
    require(index in 0 until sharpVectorCount) { "index: $index" }
    return when (index / 128) {
        0 -> sharpVectorPath000(index)
        1 -> sharpVectorPath001(index)
        2 -> sharpVectorPath002(index)
        3 -> sharpVectorPath003(index)
        4 -> sharpVectorPath004(index)
        5 -> sharpVectorPath005(index)
        6 -> sharpVectorPath006(index)
        7 -> sharpVectorPath007(index)
        8 -> sharpVectorPath008(index)
        9 -> sharpVectorPath009(index)
        10 -> sharpVectorPath010(index)
        11 -> sharpVectorPath011(index)
        12 -> sharpVectorPath012(index)
        13 -> sharpVectorPath013(index)
        14 -> sharpVectorPath014(index)
        15 -> sharpVectorPath015(index)
        16 -> sharpVectorPath016(index)
        17 -> sharpVectorPath017(index)
        18 -> sharpVectorPath018(index)
        19 -> sharpVectorPath019(index)
        20 -> sharpVectorPath020(index)
        21 -> sharpVectorPath021(index)
        22 -> sharpVectorPath022(index)
        23 -> sharpVectorPath023(index)
        24 -> sharpVectorPath024(index)
        25 -> sharpVectorPath025(index)
        26 -> sharpVectorPath026(index)
        27 -> sharpVectorPath027(index)
        28 -> sharpVectorPath028(index)
        29 -> sharpVectorPath029(index)
        else -> error("unreachable index: $index")
    }
}
